//! Strobe fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for local_tick in [0u64,49999,50000,124999,125000,500000,1000000] {for (duration,period,blend,color) in [(0.125,0.5,0.0,[1.0;4]),(0.0,0.0,0.0,[1.0;4]),(0.05,0.5,50.0,[-1.0,2.0,0.5,0.0]),(0.02,0.0,100.0,[0.0,0.8,0.2,1.0])] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<[f32;4]>=rgba.chunks_exact(4).map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let mut image=Image{w,h,px:input.iter().flatten().copied().collect()};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="strobe").unwrap().instance();
  effect.params.insert("duration".into(),Param::new(ParamValue::Float(duration)));
  effect.params.insert("period".into(),Param::new(ParamValue::Float(period)));
  effect.params.insert("blend".into(),Param::new(ParamValue::Float(blend)));
  effect.params.insert("color".into(),Param::new(ParamValue::Color(color)));
  let cx=FxCtx{t:filmcraft_time::Tick(local_tick as i64),px_scale:1.0,seconds:local_tick as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"localTick":local_tick,"parameters":{"duration":duration,"period":period,"blend":blend,"color":color},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}
 let mut media=vec![];
 for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,128]}).collect();
  let input:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
  let mut image=Image{w:16,h:16,px:input};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="strobe").unwrap().instance();
  effect.params.insert("color".into(),Param::new(ParamValue::Color([1.0,(tick as f64/500000.0)as f32,0.0,0.0])));
  effect.params.insert("blend".into(),Param::new(ParamValue::Float(tick as f64/500000.0*50.0)));
  effect.params.insert("duration".into(),Param::new(ParamValue::Float(0.125)));
  effect.params.insert("period".into(),Param::new(ParamValue::Float(0.5)));
  let cx=FxCtx{t:filmcraft_time::Tick(tick as i64),px_scale:1.0,seconds:tick as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let clock=tick+index*100000;
   let local=clock.min(500000);
   effect.params.insert("color".into(),Param::new(ParamValue::Color([1.0,(local as f64/500000.0)as f32,0.0,0.0])));
  effect.params.insert("blend".into(),Param::new(ParamValue::Float(local as f64/500000.0*50.0)));
  effect.params.insert("duration".into(),Param::new(ParamValue::Float(0.125)));
  effect.params.insert("period".into(),Param::new(ParamValue::Float(0.5)));
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut frame=Image{w:16,h:16,px};
   let cx=FxCtx{t:filmcraft_time::Tick(clock as i64),px_scale:1.0,seconds:clock as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut frame,&effect,&cx);
   frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"localTick":tick,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"frames":frames}));
 }
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));
}
